Lemma rw_cells_C8_zero_bytes : forall mm A, rw_cells bsegs mm A [C8 (wz 0)] -> rw_cells bsegs mm A [C1 (b8 0); CB 7 (repeat (b8 0) 7)].
Proof.
  intros mm A [[Hwf Hb] Hw]. split; [split|].
  - cbn. repeat split; reflexivity.
  - cbn [cells_bytes cbytes app] in *. exact Hb.
  - exact Hw.
Qed.

