(* [comment removed for export] *)
(* [comment removed for export] *)
Definition efs_new (nfreed : Z) : Z := round_up (4 * nfreed) kFreeArrayMapSize.

Definition efs_seg1_post (ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 a6 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo R FAB mfa nfreed : Z) : machine_state -> Prop :=
  fun ms' => exists m' (j8 j44 : list byte),
    let cur := FAB + mfa in let sz := efs_new nfreed - mfa in
    ms' = MS (mkR (wz 0x088a18) (Z_to_bv 64 (bv_unsigned sp + -176)) gp tp t0 t1 t2 (wz sz) (wz 1) (wz cur) (wz sz) (wz 3) (wz 50) (Z_to_bv 64 (-1)) (wz 0) a6 (wz 222)
                  (wz cur) (wz 0x1a751) (wz APAGESZ) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x086c58) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 448, bv_unsigned sp)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -176)
    /\ rw_cells bsegs m' (bv_unsigned sp + -176) [C4 (wz 50); CB 44 j44; C8 s4; C8 (wz R); C8 (wz sz); C8 (wz cur); C8 (wz sz); C8 (wz 0x092084)]   (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -80) [C8 (wz sz); C8 (wz cur); C8 (wz (efs_new nfreed)); C8 (wz 0x530d0)]                          (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -48) [CB 8 j8; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Section Seg1.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo R rbeg nfreed nf mfa au mu : Z).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 448 <= bv_unsigned sp.   (* [comment removed for export] *)
  Hypothesis Ha0 : a0 = wz AINST. Hypothesis Ha1 : a1 = wz R. Hypothesis Ha2 : a2 = wz rbeg. Hypothesis Ha3 : a3 = wz nfreed.
  Hypothesis RR : AHI_LO <= R /\ R + 128 <= aceil.
  Hypothesis RB : AHI_LO <= rbeg /\ rbeg + 2^32 <= aceil /\ rbeg mod 65536 = 0.
  Hypothesis NF : 0 <= nfreed /\ mfa < 4 * nfreed /\ 4 * nfreed <= kFreeArraySize /\ 0 <= mfa /\ mfa mod kFreeArrayMapSize = 0.
  Hypothesis RI : rw_cells bsegs m R (rinfo_cells nf mfa au mu).
  Hypothesis PMH : rw_cells bsegs m (AINST + 56) [C8 (wz 0)].
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis PSC : rw_cells bsegs m APAGESZ [C8 (wz 4096)].
  Hypothesis DPM : rw_cells bsegs m (ACFLAGS + 260) [C1 (b8 0)].

  Theorem efs_seg1 :
    evt bsegs (efs_seg1_post ra sp gp tp t0 t1 t2 s0 s1 s2 s3 s4 s5 a6 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m lo R (rbeg + kFreeArrayOffset) mfa nfreed)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
