(* [comment removed for export] *)
(* [comment removed for export] *)
Definition efs_seg2_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo R TH cur sz nf au mu newfa : Z) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz 1) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 208, bv_unsigned sp); (sh cur, sh cur + sz / 8); (TH + 2800, TH + 3168); (R + 24, R + 32)]%Z m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' R (rinfo_cells nf newfa au mu)
    /\ poisoned m' cur (Z.to_nat (sz / 8)) 0xfa
    /\ stk bsegs m' (TH + 2800) (TH + 3168).

Section Seg2.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m : mem).
  Variables (lo R cur sz newfa nf mfa au mu TSD CTX TH : Z) (j8 j44 sbs : list byte).
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -176).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 448 <= bv_unsigned sp. Hypothesis SPT : bv_unsigned sp + 16 <= 2^47. Hypothesis SPA : bv_unsigned sp mod 16 = 0.
  Hypothesis F144 : rw_cells bsegs m (bv_unsigned sp + -176) [C4 (wz 50); CB 44 j44; C8 s4; C8 (wz R); C8 (wz sz); C8 (wz cur); C8 (wz sz); C8 (wz 0x092084)].   (* [comment removed for export] *)
  Hypothesis F80 : rw_cells bsegs m (bv_unsigned sp + -80) [C8 (wz sz); C8 (wz cur); C8 (wz newfa); C8 (wz 0x530d0)].                                  (* [comment removed for export] *)
  Hypothesis F48 : rw_cells bsegs m (bv_unsigned sp + -48) [CB 8 j8; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].
  Hypothesis RR : AHI_LO <= R /\ R + 128 <= aceil.
  Hypothesis CUR : AHI_LO <= cur /\ cur + sz <= aceil /\ cur mod 4096 = 0 /\ sz mod 4096 = 0 /\ 0 < sz /\ 0 <= newfa < 2^64.
  Hypothesis TPR : 4096 <= bv_unsigned tp /\ bv_unsigned tp + 4096 <= AIMG_TOP.
  Hypothesis RNG : 6354608 <= TSD /\ TSD + 8 <= AIMG_TOP /\ aapp CTX 160 /\ CTX + 160 <= aceil /\ akobj TH 4096 /\ TH + 4096 <= aceil.
  Hypothesis SEP : hidden ((TH + 4096 <= R \/ R + 128 <= TH) /\ (TH + 4096 <= cur \/ cur + sz <= TH) /\ (R + 128 <= cur \/ cur + sz <= R)).
  Hypothesis RI : rw_cells bsegs m R (rinfo_cells nf mfa au mu).
  Hypothesis TST : stk bsegs m (TH + 2800) (TH + 3168).
  Hypothesis SH : u8arr bsegs m (sh cur) sbs. Hypothesis SHL : Z.of_nat (length sbs) = sz / 8.
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis MLIM : rw_cells bsegs m (ACFLAGS + 144) [C8 (wz 0)].
  Hypothesis CTHR : rw_cells bsegs m (ACFLAGS + 120) [C8 (wz 0xffffffffffffffff)].
  Hypothesis CCAN : rw_cells bsegs m ACANPOISON [C1 (b8 1)].
  Hypothesis CSHB : rw_cells bsegs m ASHBASE_CELL [C8 (wz ASHADOW_BASE)].
